fn average(values: &[i32]) -> f64 {
    let sum: i32 = values.iter().sum();
    sum as f64 / values.len() as f64
}

fn main() {
    // 预留容量：三次 push 都不会触发扩容
    let mut with_cap: Vec<i32> = Vec::with_capacity(3);
    for v in [2, 4, 6] {
        with_cap.push(v);
    }
    println!("len={} cap={}", with_cap.len(), with_cap.capacity());

    // 不预留：观察扩容在增长过程中发生
    let mut growing: Vec<i32> = Vec::new();
    let mut expanded = false;
    for v in 0..8 {
        let before = growing.capacity();
        growing.push(v);
        if growing.capacity() != before {
            expanded = true;
        }
    }
    println!("grew_len={} expanded={}", growing.len(), expanded);

    // &Vec<i32> 通过 Deref 自动变成 &[i32]
    let data = vec![10, 20, 30, 40];
    let slice: &[i32] = &data;
    println!("average={:.1}", average(slice));
    println!("last={}", slice.last().copied().unwrap_or(-1));
}

