fn running_max(values: &[i32]) -> Vec<i32> {
    let mut out = Vec::with_capacity(values.len());
    let mut best = i32::MIN;
    for &v in values {
        if v > best {
            best = v;
        }
        out.push(best);
    }
    out
}

