use std::collections::{BTreeMap, HashMap};

fn word_counts(text: &str) -> HashMap<String, u32> {
    let mut counts: HashMap<String, u32> = HashMap::new();
    for word in text.split_whitespace() {
        *counts.entry(word.to_string()).or_insert(0) += 1;
    }
    counts
}

fn main() {
    let text = "red blue red green blue red";
    let counts = word_counts(text);

    // HashMap 顺序不定：先排序键再打印，保证输出确定
    let mut keys: Vec<&String> = counts.keys().collect();
    keys.sort();
    for k in keys {
        println!("hash {}={}", k, counts[k]);
    }

    // BTreeMap：天然有序，可直接迭代与范围查询
    let mut scores: BTreeMap<&str, i32> = BTreeMap::new();
    scores.insert("alice", 90);
    scores.insert("bob", 75);
    scores.insert("carol", 82);
    scores.insert("dave", 60);
    for (name, score) in &scores {
        println!("{} -> {}", name, score);
    }
    let passing: Vec<&str> = scores
        .range("bob"..="carol")
        .map(|(name, _)| *name)
        .collect();
    println!("range={:?}", passing);
}

