use std::collections::{BTreeSet, HashSet};

fn dedup_keep_order(items: &[&str]) -> Vec<String> {
    let mut seen: HashSet<&str> = HashSet::new();
    let mut out: Vec<String> = Vec::new();
    for &item in items {
        if seen.insert(item) {
            out.push(item.to_string());
        }
    }
    out
}

fn main() {
    let raw = ["b", "a", "b", "c", "a", "b"];
    println!("dedup={:?}", dedup_keep_order(&raw));

    let a: BTreeSet<i32> = [1, 2, 3, 4].into_iter().collect();
    let b: BTreeSet<i32> = [3, 4, 5, 6].into_iter().collect();
    let inter: Vec<i32> = a.intersection(&b).copied().collect();
    let union: Vec<i32> = a.union(&b).copied().collect();
    let only_a: Vec<i32> = a.difference(&b).copied().collect();
    println!("inter={:?}", inter);
    println!("union={:?}", union);
    println!("only_a={:?}", only_a);
}

