use std::iter;

fn main() {
    // 惰性：没有消费器前不会执行 filter/map
    let lazy = (1..=10).filter(|n| n % 3 == 0).map(|n| n * 10);
    let collected: Vec<i32> = lazy.collect();
    println!("collected={:?}", collected);

    // chain 拼接两个不同来源
    let head = [1, 2];
    let tail = (3..=5).collect::<Vec<i32>>();
    let chained: Vec<i32> = head.iter().copied().chain(tail.iter().copied()).collect();
    println!("chained={:?}", chained);

    // once 加入单个前缀，repeat + take 生成重复序列
    let with_zero = iter::once(0).chain(chained.iter().copied());
    let prefix: Vec<i32> = with_zero.take(4).collect();
    println!("prefix={:?}", prefix);

    let repeated: Vec<&str> = iter::repeat("x").take(3).collect();
    println!("repeated={:?}", repeated);

    // 单次遍历完成求和与计数，避免中间集合
    let (sum, count) = (1..=5).fold((0, 0), |(s, c), x| (s + x, c + 1));
    println!("sum={} count={}", sum, count);
}

