    println!("shout={}", shout());

    // 闭包作为值返回：必须 move 才能把 n 带出函数
    fn make_adder(n: i32) -> impl Fn(i32) -> i32 {
        move |x| x + n
    }
    let add7 = make_adder(7);
    println!("add7(3)={}", add7(3));
}

