struct Fibonacci {
    a: u64,
    b: u64,
    remaining: usize,
}

impl Fibonacci {
    fn new(count: usize) -> Self {
        Fibonacci { a: 0, b: 1, remaining: count }
    }
}

impl Iterator for Fibonacci {
    type Item = u64;

    fn next(&mut self) -> Option<u64> {
        if self.remaining == 0 {
            return None;
        }
        let current = self.a;
        let next = self.a + self.b;
        self.a = self.b;
        self.b = next;
        self.remaining -= 1;
        Some(current)
    }
}

fn main() {
    let fibs: Vec<u64> = Fibonacci::new(8).collect();
    println!("fibs={:?}", fibs);

    // 自定义迭代器直接接入标准适配器
    let even_fibs: Vec<u64> = Fibonacci::new(10).filter(|n| n % 2 == 0).collect();
    println!("even_fibs={:?}", even_fibs);

    let total: u64 = Fibonacci::new(10).sum();
    println!("total={}", total);
}

