struct Countdown {
    current: u32,
}

impl Countdown {
    fn new(n: u32) -> Self {
        Countdown { current: n }
    }
}

impl Iterator for Countdown {
    type Item = u32;

    fn next(&mut self) -> Option<u32> {
        if self.current == 0 {
            None
        } else {
            let value = self.current;
            self.current -= 1;
            Some(value)
        }
    }
}

fn main() {
    let values: Vec<u32> = Countdown::new(5).collect();
    println!("{:?}", values);
    println!("sum={}", Countdown::new(5).sum::<u32>());
}

