use std::collections::HashMap;

fn busiest(logs: &[&str]) -> Option<(String, u32)> {
    let mut counts: HashMap<String, u32> = HashMap::new();
    for line in logs {
        let mut parts = line.split_whitespace();
        let _level = parts.next();
        if let Some(process) = parts.next() {
            *counts.entry(process.to_string()).or_insert(0) += 1;
        }
    }
    counts.into_iter().max_by_key(|(_, count)| *count)
}

fn main() {
    let logs = [
        "INFO api started",
        "WARN db slow",
        "INFO worker ready",
        "ERROR api timeout",
        "INFO api handled",
        "ERROR db deadlock",
    ];
    let (name, count) = busiest(&logs).unwrap();
    println!("{}={}", name, count);
}

