    match divide(10, 0) {
        Ok(v) => println!("ok={}", v),
        Err(e) => println!("err={}", e),
    }
    // i32::MIN / -1 在普通 `/` 下会 panic；checked_div 返回 None。
    match divide(i32::MIN, -1) {
        Ok(v) => println!("ok={}", v),
        Err(e) => println!("err={}", e),
    }

    println!("port={:?}", parse_port("8080"));
    println!("port={:?}", parse_port("99999"));
}

