    let mut total = 0;
    for line in lines {
        let (_, count) = line.split_once(':').unwrap_or((line, "0"));
        total += count.trim().parse::<usize>()?;
    }
    Ok(total)
}

fn main() {
    println!("{:?}", total_length(&["a:2", "b:3"]));
    println!("{:?}", total_length(&["a:2", "b:x"]).is_err());
}

