#[derive(Debug)]
enum CalcError {
    DivByZero,
    Overflow,
    BadOperand(String),
}

impl fmt::Display for CalcError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            CalcError::DivByZero => write!(f, "division by zero"),
            CalcError::Overflow => write!(f, "arithmetic overflow"),
            CalcError::BadOperand(s) => write!(f, "bad operand: {s}"),
        }
    }
}

impl Error for CalcError {}

fn calc(a: i32, b: i32) -> Result<i32, CalcError> {
    if b == 0 {
        return Err(CalcError::DivByZero);
    }
    // checked_div 同时覆盖除零与 i32::MIN / -1 溢出
    a.checked_div(b).ok_or(CalcError::Overflow)
}

fn main() {
    println!("{:?}", calc(10, 2));
    println!("{}", calc(10, 0).unwrap_err());
    println!("{}", calc(i32::MIN, -1).unwrap_err());
}

