#[derive(Debug, PartialEq)]
struct Stack {
    items: Vec<i32>,
}

impl Stack {
    fn new() -> Self {
        Stack { items: Vec::new() }
    }
    fn push(&mut self, value: i32) {
        self.items.push(value);
    }
    fn pop(&mut self) -> i32 {
        self.items.pop().expect("pop on empty stack")
    }
    fn len(&self) -> usize {
        self.items.len()
    }
}

fn sample_stack() -> Stack {
    let mut s = Stack::new();
    s.push(1);
    s.push(2);
    s
}

