fn parse(v: &str) -> (u64, u64, u64) {
    let mut it = v.split('.');
    (
        it.next().unwrap().parse().unwrap(),
        it.next().unwrap().parse().unwrap(),
        it.next().unwrap().parse().unwrap(),
    )
}

fn bump_level(current: &str, next: &str) -> &'static str {
    let (a, b) = (parse(current), parse(next));
    if a == b {
        "none"
    } else if a.0 != b.0 {
        "major"
    } else if a.1 != b.1 {
        "minor"
    } else {
        "patch"
    }
}

fn main() {
    println!("{}", bump_level("1.2.3", "1.2.4"));
    println!("{}", bump_level("1.2.3", "1.3.0"));
    println!("{}", bump_level("1.2.3", "2.0.0"));
    println!("{}", bump_level("1.2.3", "1.2.3"));
}

