/// 计算两点之间的欧氏距离。
///
/// 示例：
/// ```
/// let d = distance(0.0, 0.0, 3.0, 4.0);
/// assert!((d - 5.0).abs() < 1e-9);
/// ```
fn distance(x1: f64, y1: f64, x2: f64, y2: f64) -> f64 {
    ((x2 - x1).powi(2) + (y2 - y1).powi(2)).sqrt()
}

fn main() {
    // 与文档示例相同的断言
    let d = distance(0.0, 0.0, 3.0, 4.0);
