enum List {
    Nil,
    Cons(i32, Box<List>),
}

impl List {
    fn len(&self) -> usize {
        match self {
            List::Nil => 0,
            List::Cons(_, rest) => 1 + rest.len(),
        }
    }

    fn to_vec(&self) -> Vec<i32> {
        let mut out = Vec::new();
        let mut cur = self;
        while let List::Cons(v, rest) = cur {
            out.push(*v);
            cur = rest;
        }
        out
    }
}

fn main() {
