use std::cell::RefCell;
use std::rc::Rc;

type NodeRef = Rc<RefCell<Node>>;

#[derive(Debug)]
struct Node {
    value: i32,
    next: Option<NodeRef>,
}

fn push_front(head: &Option<NodeRef>, value: i32) -> NodeRef {
    Rc::new(RefCell::new(Node { value, next: head.clone() }))
}

fn collect(head: &Option<NodeRef>) -> Vec<i32> {
    let mut out = Vec::new();
    let mut current = head.clone();
    while let Some(node) = current {
        out.push(node.borrow().value);
        current = node.borrow().next.clone();
    }
    out
}

fn main() {
    let list = push_front(&None, 3);
    let list = push_front(&Some(list), 2);
    let list = push_front(&Some(list), 1);
    println!("values={:?}", collect(&Some(list.clone())));
    println!("strong_count_head={}", Rc::strong_count(&list));

    // 通过共享引用修改一个节点（内部可变性）
    if let Some(first) = list.borrow().next.clone() {
        first.borrow_mut().value = 20;
    }
    println!("after_edit={:?}", collect(&Some(list)));
}

