    println!("root strong={} weak={}", Rc::strong_count(&root), Rc::weak_count(&root));
    println!("child strong={}", Rc::strong_count(&child));

    // 通过 Weak 向上找到父节点
    let parent = child.parent.borrow().upgrade();
    match parent {
        Some(p) => println!("child parent={}", p.name),
        None => println!("child parent=<dropped>"),
    }

    let orphans = {
        let temp = Rc::new(Node {
            name: String::from("temp"),
            parent: RefCell::new(Weak::new()),
            children: RefCell::new(Vec::new()),
        });
        Rc::downgrade(&temp)
    };
    // temp 的强引用已归零，upgrade 返回 None
    println!("orphan_revived={}", orphans.upgrade().is_some());
