use std::cell::Cell;

struct Metrics {
    hits: Cell<u32>,
    enabled: Cell<bool>,
}

impl Metrics {
    fn new() -> Self {
        Metrics { hits: Cell::new(0), enabled: Cell::new(true) }
    }

    fn record(&self) {
        if self.enabled.get() {
            self.hits.set(self.hits.get() + 1);
        }
    }

    fn disable(&self) {
        self.enabled.set(false);
    }

    fn hits(&self) -> u32 {
        self.hits.get()
    }
}

fn main() {
    let m = Metrics::new();
    m.record();
    m.record();
    println!("hits={}", m.hits());

    m.disable();
    m.record();
    println!("hits_after_disable={}", m.hits());

    // replace 返回旧值，不要求 Copy
    let old = m.enabled.replace(true);
    println!("old_enabled={} new_enabled={}", old, m.enabled.get());
    m.record();
    println!("hits_final={}", m.hits());

    // 非 Copy 类型也能用 Cell：take 要求 Default，可整体移出
    let name = Cell::new(String::from("owner"));
    let taken = name.take();
    println!("taken={} left_empty={}", taken, name.into_inner().is_empty());
}

