use std::cell::{Cell, RefCell};
use std::collections::BTreeMap;

struct Cache {
    map: RefCell<BTreeMap<String, i32>>,
    hits: Cell<u32>,
}

impl Cache {
    fn new() -> Self {
        Cache { map: RefCell::new(BTreeMap::new()), hits: Cell::new(0) }
    }

    fn get_or_insert(&self, key: &str, value: i32) -> i32 {
        if let Some(existing) = self.map.borrow().get(key).copied() {
            self.hits.set(self.hits.get() + 1);
            return existing;
        }
        self.map.borrow_mut().insert(key.to_string(), value);
        value
    }
}

fn main() {
    let cache = Cache::new();
    println!("first={}", cache.get_or_insert("k", 42));
    println!("second={}", cache.get_or_insert("k", 99));
    println!("hits={}", cache.hits.get());
}

