// 阻塞式：一次做完所有工作，期间无法被调度出去
fn blocking_sum(limit: u64) -> u64 {
    (1..=limit).sum()
}

// 协作式：用状态机把工作拆成多步，每步返回一个‘还要不要再走’的信号。
// 这是 poll 返回 Pending 的语义模型：每步之间控制权交回调用方。
struct StepSum {
    limit: u64,
    next: u64,
    step: u64,
    total: u64,
}

impl StepSum {
    fn new(limit: u64, step: u64) -> Self {
        StepSum { limit, next: 1, step, total: 0 }
    }

    /// 推进一小步。返回 None 表示已完成（对应 Poll::Ready），
    /// 返回 Some(()) 表示还可以再推进（对应 Poll::Pending 后被再次调度）。
    fn step_once(&mut self) -> Option<()> {
        if self.next > self.limit {
            return None;
        }
        let end = (self.next + self.step - 1).min(self.limit);
        self.total += (self.next..=end).sum::<u64>();
        self.next = end + 1;
        Some(())
    }
}

fn main() {
    let blocking = blocking_sum(10_000);

    // 执行器视角：反复推进一个任务，直到它报告完成
    let mut task = StepSum::new(10_000, 1000);
    let mut steps = 0;
    while task.step_once().is_some() {
        steps += 1;
    }
    println!("blocking={}", blocking);
    println!("cooperative={}", task.total);
    println!("equal={}", blocking == task.total);
    println!("steps={}", steps);
}

