use std::marker::PhantomPinned;
use std::pin::Pin;

struct Counter {
    count: i32,
    _pin: PhantomPinned,
}

fn bump(mut pinned: Pin<&mut Counter>, delta: i32) {
    // 该结构无自引用，未移动内存，因此这里安全
    let inner = unsafe { pinned.as_mut().get_unchecked_mut() };
    inner.count += delta;
}

fn main() {
    let mut counter = Box::pin(Counter { count: 0, _pin: PhantomPinned });
    bump(counter.as_mut(), 5);
    println!("{}", counter.count);
}

