        assert!(event.complete(value));
    });
    (future, producer)
}

async fn compute(wait: WaitValue<i32>, started: Arc<AtomicUsize>) -> i32 {
    started.fetch_add(1, Ordering::SeqCst);
    let base = wait.await;
    base * 2
}

