use std::future::Future;
use std::pin::Pin;
use std::task::{Context, Poll, Waker};

// 等两个都完成。子 Future 装进 Pin<Box<..>>（堆上固定），
// 因此组合子自身是 Unpin，poll 里可用 get_mut 拿到 &mut Self。
struct Join2<A: Future, B: Future> {
    a: Option<Pin<Box<A>>>,
    b: Option<Pin<Box<B>>>,
    a_out: Option<A::Output>,
    b_out: Option<B::Output>,
}

impl<A: Future, B: Future> Join2<A, B> {
    fn new(a: A, b: B) -> Self {
        Join2 { a: Some(Box::pin(a)), b: Some(Box::pin(b)), a_out: None, b_out: None }
    }
}

impl<A: Future, B: Future> Future for Join2<A, B>
where
    A::Output: Unpin,
    B::Output: Unpin,
{
    type Output = (A::Output, B::Output);

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.get_mut();
        if this.a_out.is_none() {
            if let Some(a) = this.a.as_mut() {
                if let Poll::Ready(value) = a.as_mut().poll(cx) {
                    this.a_out = Some(value);
                    this.a = None;
                }
            }
        }
        if this.b_out.is_none() {
            if let Some(b) = this.b.as_mut() {
                if let Poll::Ready(value) = b.as_mut().poll(cx) {
                    this.b_out = Some(value);
                    this.b = None;
                }
            }
        }
        // 两边都就绪才能返回；无论谁先完成都不会 panic
        match (this.a_out.take(), this.b_out.take()) {
            (Some(a), Some(b)) => Poll::Ready((a, b)),
            (a, b) => {
                this.a_out = a;
                this.b_out = b;
                Poll::Pending
            }
        }
    }
}

// 等任一完成。用枚举表达哪一方先赢。
enum Either<A, B> {
    Left(A),
    Right(B),
}

struct Select2<A: Future, B: Future> {
    a: Pin<Box<A>>,
    b: Pin<Box<B>>,
}

impl<A: Future, B: Future> Future for Select2<A, B> {
    type Output = Either<A::Output, B::Output>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.get_mut();
        // 先 poll a，再 poll b：任一方 Ready 即返回
        if let Poll::Ready(value) = this.a.as_mut().poll(cx) {
            return Poll::Ready(Either::Left(value));
        }
        if let Poll::Ready(value) = this.b.as_mut().poll(cx) {
            return Poll::Ready(Either::Right(value));
        }
        Poll::Pending
    }
}

async fn value(v: i32) -> i32 {
    v
}

fn block_on<F: Future>(mut future: F) -> F::Output {
    let waker = Waker::noop();
    let mut cx = Context::from_waker(waker);
    let mut future = unsafe { Pin::new_unchecked(&mut future) };
    loop {
        if let Poll::Ready(value) = future.as_mut().poll(&mut cx) {
            return value;
        }
    }
}

fn main() {
    let joined = block_on(Join2::new(value(3), value(4)));
    println!("joined={:?}", joined);

    match block_on(Select2 { a: Box::pin(value(10)), b: Box::pin(value(20)) }) {
        Either::Left(v) => println!("selected_left={}", v),
        Either::Right(v) => println!("selected_right={}", v),
    }
}

