use std::future::Future;
use std::pin::Pin;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::{mpsc, Arc, Condvar, Mutex};
use std::task::{Context, Poll, Wake, Waker};
use std::thread::{self, JoinHandle};

struct Notify {
    signalled: Mutex<bool>,
    changed: Condvar,
    polls: AtomicUsize,
    wakes: AtomicUsize,
}
impl Notify {
    fn new() -> Arc<Self> {
        Arc::new(Self { signalled: Mutex::new(false), changed: Condvar::new(),
            polls: AtomicUsize::new(0), wakes: AtomicUsize::new(0) })
    }
    fn signal(&self) {
        self.wakes.fetch_add(1, Ordering::SeqCst);
        *self.signalled.lock().unwrap() = true;
        self.changed.notify_one();
    }
    fn wait(&self) {
        let mut signalled = self.signalled.lock().unwrap();
        while !*signalled { signalled = self.changed.wait(signalled).unwrap(); }
        *signalled = false;
    }
}
impl Wake for Notify {
    fn wake(self: Arc<Self>) { self.signal(); }
    fn wake_by_ref(self: &Arc<Self>) { self.signal(); }
}

fn block_on<F: Future>(future: F, notify: Arc<Notify>) -> F::Output {
    let waker = Waker::from(Arc::clone(&notify));
    let mut context = Context::from_waker(&waker);
    let mut future = Box::pin(future);
    loop {
        notify.polls.fetch_add(1, Ordering::SeqCst);
        match future.as_mut().poll(&mut context) {
            Poll::Ready(value) => return value,
            // A wake before this wait is retained in the mutex predicate.
            Poll::Pending => notify.wait(),
        }
    }
}

struct EventState<T> { value: Option<T>, waker: Option<Waker> }
struct Event<T> { state: Mutex<EventState<T>> }
impl<T> Event<T> {
    fn new() -> Self { Self { state: Mutex::new(EventState { value: None, waker: None }) } }
    fn complete(&self, value: T) -> bool {
        let waker = {
            let mut state = self.state.lock().unwrap();
            if state.value.is_some() { return false; }
            state.value = Some(value);
            state.waker.take()
        };
        // Scheduling is outside the event lock, so it cannot re-enter it.
        if let Some(waker) = waker { waker.wake(); }
        true
    }
}

struct WaitValue<T> {
    event: Arc<Event<T>>,
    first_pending: Option<mpsc::SyncSender<()>>,
}
impl<T: Clone> Future for WaitValue<T> {
    type Output = T;
    fn poll(mut self: Pin<&mut Self>, context: &mut Context<'_>) -> Poll<T> {
        let event = Arc::clone(&self.event);
        let mut state = event.state.lock().unwrap();
        if let Some(value) = &state.value { return Poll::Ready(value.clone()); }
        // The same mutex protects readiness and registration. A producer
        // cannot publish in the gap between checking and storing the waker.
        state.waker = Some(context.waker().clone());
        if let Some(started) = self.first_pending.take() {
            started.send(()).expect("producer waiting for first Pending");
        }
        Poll::Pending
    }
}

fn event_pair<T>() -> (WaitValue<T>, Arc<Event<T>>, mpsc::Receiver<()>) {
    let event = Arc::new(Event::new());
    let (started, registered) = mpsc::sync_channel(1);
    (WaitValue { event: Arc::clone(&event), first_pending: Some(started) }, event, registered)
}

fn after_pending<T: Clone + Send + 'static>(value: T) -> (WaitValue<T>, JoinHandle<()>) {
    let (future, event, registered) = event_pair();
    let producer = thread::spawn(move || {
        registered.recv().expect("first Pending handshake");
        assert!(event.complete(value));
    });
    (future, producer)
}

// A teaching timer uses one OS thread per event, not a shared I/O reactor.
fn timer_event(label: &'static str, delay: std::time::Duration)
    -> (WaitValue<&'static str>, JoinHandle<()>) {
    let (future, event, registered) = event_pair();
    let producer = thread::spawn(move || {
        registered.recv().expect("timer registered before deadline starts");
        // The live sender keeps this channel connected. With no messages,
        // recv_timeout waits for a real deadline; it does not order the polls.
        let (hold_open, clock) = mpsc::channel::<()>();
        assert!(matches!(clock.recv_timeout(delay), Err(mpsc::RecvTimeoutError::Timeout)));
        drop(hold_open);
        assert!(event.complete(label));
    });
    (future, producer)
}

fn main() {
    let notify = Notify::new();
    let (timer, producer) = timer_event("timer fired", std::time::Duration::from_millis(2));
    let message = block_on(async move { timer.await }, Arc::clone(&notify));
    producer.join().unwrap();
    assert_eq!(notify.polls.load(Ordering::SeqCst), 2);
    assert_eq!(notify.wakes.load(Ordering::SeqCst), 1);
    println!("{message}");
    println!("wake_calls={}", notify.wakes.load(Ordering::SeqCst));
    println!("tokio_call_shape: block_on(async {{ ... }})");
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn completion_before_poll_is_immediately_ready_without_a_wake() {
        let event = Arc::new(Event::new());
        assert!(event.complete(9));
        assert!(!event.complete(10));
        let notify = Notify::new();
        let wait = WaitValue { event, first_pending: None };
        assert_eq!(block_on(wait, Arc::clone(&notify)), 9);
        assert_eq!(notify.polls.load(Ordering::SeqCst), 1);
        assert_eq!(notify.wakes.load(Ordering::SeqCst), 0);
    }
    #[test]
    fn latest_pending_waker_replaces_the_previous_registration() {
        let event = Arc::new(Event::new());
        let mut wait = Box::pin(WaitValue { event: Arc::clone(&event), first_pending: None });
        let first = Notify::new();
        let second = Notify::new();
        let waker_a = Waker::from(Arc::clone(&first));
        let waker_b = Waker::from(Arc::clone(&second));
        assert!(wait.as_mut().poll(&mut Context::from_waker(&waker_a)).is_pending());
        assert!(wait.as_mut().poll(&mut Context::from_waker(&waker_b)).is_pending());
        assert!(event.complete(7));
        assert_eq!(first.wakes.load(Ordering::SeqCst), 0);
        assert_eq!(second.wakes.load(Ordering::SeqCst), 1);
        assert_eq!(wait.as_mut().poll(&mut Context::from_waker(&waker_b)), Poll::Ready(7));
    }
    #[test]
    fn registered_events_always_finish_with_one_real_wake() {
        for value in 0..32 {
            let notify = Notify::new();
            let (wait, producer) = after_pending(value);
            assert_eq!(block_on(wait, Arc::clone(&notify)), value);
            producer.join().unwrap();
            assert_eq!(notify.polls.load(Ordering::SeqCst), 2);
            assert_eq!(notify.wakes.load(Ordering::SeqCst), 1);
        }
    }
}

