use proc_macro::TokenStream;

/// 只依赖 std proc_macro 的派生宏（无 syn/quote，离线可用）。
/// 从输入 token 文本里找出 `struct <Name>` 并统计字段数。
#[proc_macro_derive(Describe)]
pub fn derive_describe(input: TokenStream) -> TokenStream {
    let source = input.to_string();
    let mut tokens = source.split_whitespace();
    let mut name = String::from("Unknown");
    while let Some(tok) = tokens.next() {
        if tok == "struct" {
            if let Some(n) = tokens.next() {
                name = n.to_string();
            }
            break;
        }
    }
    let body = source
        .split_once('{')
        .and_then(|(_, rest)| rest.rsplit_once('}'))
        .map(|(fields, _)| fields)
        .unwrap_or("");
    let field_count = body.split(',').filter(|s| !s.trim().is_empty()).count();
    format!(
        "impl {name} {{ pub fn describe(&self) -> String {{ format!(\"{name} has {field_count} fields\") }} }}"
    )
    .parse()
    .unwrap()
}

