fn split_first_mut(values: &mut [i32]) -> Option<(&mut i32, &mut [i32])> {
    let len = values.len();
    if len == 0 {
        return None;
    }
    let ptr = values.as_mut_ptr();
    // SAFETY: len >= 1，首元素与其余区间不重叠，原借用被消费
    unsafe {
        let first = &mut *ptr;
        let rest = std::slice::from_raw_parts_mut(ptr.add(1), len - 1);
        Some((first, rest))
    }
}

