fn c_str_eq(a: &[u8], b: &[u8]) -> bool {
    let mut i = 0;
    loop {
        let x = a.get(i).copied().unwrap_or(0);
        let y = b.get(i).copied().unwrap_or(0);
        if x != y {
            return false;
        }
        if x == 0 {
            return true;
        }
        i += 1;
    }
}

fn main() {
    println!("{}", c_str_eq(b"abc\0", b"abc\0"));
    println!("{}", c_str_eq(b"abc\0", b"abd\0"));
}

