use std::os::raw::c_char;

/// 导出给 C 的阶乘（用 u64 避免 C 侧类型歧义）。
#[no_mangle]
pub extern "C" fn rust_factorial(n: u64) -> u64 {
    let mut acc: u64 = 1;
    let mut i = 2;
    while i <= n {
        acc = acc.saturating_mul(i);
        i += 1;
    }
    acc
}

/// 导出：判断 C 字符串指针是否为空。
#[no_mangle]
pub extern "C" fn rust_is_null(ptr: *const c_char) -> bool {
    ptr.is_null()
}

mod ffi {
    extern "C" {
        pub fn rust_factorial(n: u64) -> u64;
    }
}

fn main() {
    println!("direct={}", rust_factorial(5));
    let via_ffi = unsafe { ffi::rust_factorial(6) };
    println!("via_ffi={}", via_ffi);
    println!("is_null={}", rust_is_null(std::ptr::null()));
}

