use std::time::Instant;

fn sum_loop(values: &[u64]) -> u64 {
    let mut total = 0;
    let mut i = 0;
    while i < values.len() {
        total += values[i];
        i += 1;
    }
    total
}

fn main() {
    let values: Vec<u64> = (1..=100_000).collect();

    let start = Instant::now();
    let loop_sum = sum_loop(&values);
    let _loop_time = start.elapsed();

    let start = Instant::now();
    let iter_sum: u64 = values.iter().sum();
    let _iter_time = start.elapsed();

    println!("equal={}", loop_sum == iter_sum);
}

