/// 解析长度为前缀的帧，返回每个帧负载的切片视图（零拷贝）。
fn parse_frames(input: &[u8]) -> Result<Vec<&[u8]>, String> {
    let mut frames = Vec::new();
    let mut cursor = 0;
    while cursor < input.len() {
        let len = input[cursor] as usize;
        cursor += 1;
        if cursor + len > input.len() {
            return Err(format!("truncated frame at {cursor}"));
        }
        frames.push(&input[cursor..cursor + len]);
        cursor += len;
    }
    Ok(frames)
}

fn main() {
    // 3 个帧："hi"(2)、"rust"(4)、"ok"(2)
    let buffer: Vec<u8> = vec![2, b'h', b'i', 4, b'r', b'u', b's', b't', 2, b'o', b'k'];
    let frames = parse_frames(&buffer).unwrap();
    println!("count={}", frames.len());
    for (index, frame) in frames.iter().enumerate() {
        println!("frame {}={}", index, std::str::from_utf8(frame).unwrap());
    }

    // 错误输入：长度超出剩余数据
    let bad = vec![5, b'x'];
    println!("error={}", parse_frames(&bad).is_err());
}

