// AoS：每个点把 x、y 相邻存放
#[derive(Clone, Copy)]
struct PointAoS {
    x: i32,
    y: i32,
}

// SoA：所有 x 与所有 y 分别连续存放
struct PointsSoA {
    xs: Vec<i32>,
    ys: Vec<i32>,
}

fn sum_x_aos(points: &[PointAoS]) -> i64 {
    points.iter().map(|p| p.x as i64).sum()
}

fn sum_x_soa(points: &PointsSoA) -> i64 {
    points.xs.iter().map(|&x| x as i64).sum()
}

fn main() {
    let count = 1000;
    let aos: Vec<PointAoS> = (0..count).map(|i| PointAoS { x: i, y: -i }).collect();
    let soa = PointsSoA {
        xs: (0..count).collect(),
        ys: (0..count).map(|i| -i).collect(),
    };

    let a = sum_x_aos(&aos);
    let b = sum_x_soa(&soa);
    println!("equal={}", a == b);
    println!("sum={}", a);
    println!("aos_point_size={}", std::mem::size_of::<PointAoS>());
    println!("soa_x_stride={}", std::mem::size_of::<i32>());
}

