#[derive(Clone, Copy)]
struct Rect {
    w: i32,
    h: i32,
}

fn total_area_aos(rects: &[Rect]) -> i64 {
    rects.iter().map(|r| (r.w * r.h) as i64).sum()
}

fn total_area_soa(widths: &[i32], heights: &[i32]) -> i64 {
    widths
        .iter()
        .zip(heights)
        .map(|(&w, &h)| (w * h) as i64)
        .sum()
}

fn main() {
    let rects: Vec<Rect> = (0..100).map(|i| Rect { w: i + 1, h: 2 }).collect();
    let widths: Vec<i32> = (0..100).map(|i| i + 1).collect();
    let heights: Vec<i32> = vec![2; 100];

    let a = total_area_aos(&rects);
    let b = total_area_soa(&widths, &heights);
    println!("equal={}", a == b);
    println!("total={}", a);
}

