use std::collections::BTreeSet;
use std::fs::{self, OpenOptions};
use std::io::{self, Write};
use std::path::{Path, PathBuf};
use std::time::{SystemTime, UNIX_EPOCH};

#[derive(Debug, Clone, PartialEq, Eq)]
struct Todo { id: u64, done: bool, title: String }

#[derive(Debug, PartialEq, Eq)]
enum Command { Add(String), Done(u64), List, Stats }

fn parse_command(args: &[String]) -> Result<Command, String> {
    match args.first().map(String::as_str) {
        Some("add") if args.len() >= 2 => {
            let title = args[1..].join(" ");
            if title.trim().is_empty() { return Err("empty title".into()); }
            Ok(Command::Add(title))
        }
        Some("done") if args.len() == 2 => {
            let id = args[1].parse::<u64>().map_err(|_| "invalid id")?;
            if id == 0 { return Err("id must be positive".into()); }
            Ok(Command::Done(id))
        }
        Some("list") if args.len() == 1 => Ok(Command::List),
        Some("stats") if args.len() == 1 => Ok(Command::Stats),
        _ => Err("usage: [--file PATH] add TITLE | done ID | list | stats".into()),
    }
}

fn escape(title: &str) -> String {
    let mut encoded = String::new();
    for character in title.chars() {
        match character {
            '\\' => encoded.push_str("\\\\"),
            '\t' => encoded.push_str("\\t"),
            '\n' => encoded.push_str("\\n"),
            '\r' => encoded.push_str("\\r"),
            other => encoded.push(other),
        }
    }
    encoded
}

fn unescape(encoded: &str) -> Result<String, String> {
    let mut result = String::new();
    let mut characters = encoded.chars();
    while let Some(character) = characters.next() {
        if character != '\\' { result.push(character); continue; }
        result.push(match characters.next() {
            Some('\\') => '\\', Some('t') => '\t',
            Some('n') => '\n', Some('r') => '\r',
            _ => return Err("invalid title escape".into()),
        });
    }
    Ok(result)
}

fn load(path: &Path) -> Result<Vec<Todo>, String> {
    let text = match fs::read_to_string(path) {
        Ok(text) => text,
        Err(error) if error.kind() == io::ErrorKind::NotFound => return Ok(Vec::new()),
        Err(error) => return Err(format!("read: {error}")),
    };
    let mut seen = BTreeSet::new();
    let mut tasks = Vec::new();
    for (index, line) in text.lines().enumerate() {
        let mut columns = line.splitn(3, '\t');
        let id = columns.next().unwrap_or("").parse::<u64>()
            .map_err(|_| format!("line {}: invalid id", index + 1))?;
        if id == 0 || !seen.insert(id) { return Err("duplicate or zero id".into()); }
        let done = match columns.next() {
            Some("0") => false, Some("1") => true,
            _ => return Err("invalid completion flag".into()),
        };
        let title = unescape(columns.next().ok_or("missing title")?)?;
        if title.trim().is_empty() { return Err("empty stored title".into()); }
        tasks.push(Todo { id, done, title });
    }
    Ok(tasks)
}

fn save(path: &Path, tasks: &[Todo]) -> Result<(), String> {
    let nonce = SystemTime::now().duration_since(UNIX_EPOCH).map_err(|e| e.to_string())?.as_nanos();
    let temporary = path.with_extension(format!("tmp-{}-{nonce}", std::process::id()));
    let result = (|| -> Result<(), String> {
        let mut file = OpenOptions::new().write(true).create_new(true).open(&temporary)
            .map_err(|e| format!("temporary file: {e}"))?;
        for task in tasks {
            writeln!(file, "{}\t{}\t{}", task.id, u8::from(task.done), escape(&task.title))
                .map_err(|e| format!("write: {e}"))?;
        }
        file.sync_all().map_err(|e| format!("flush: {e}"))?;
        drop(file);
        fs::rename(&temporary, path).map_err(|e| format!("replace: {e}"))
    })();
    if result.is_err() { let _ = fs::remove_file(&temporary); }
    result
}

fn rows(tasks: &[Todo]) -> String {
    tasks.iter().map(|task| format!("{} [{}] {}\n", task.id,
        if task.done { "x" } else { " " }, task.title)).collect()
}

fn execute(path: &Path, command: Command) -> Result<String, String> {
    let mut tasks = load(path)?;
    match command {
        Command::Add(title) => {
            let id = tasks.iter().map(|t| t.id).max().unwrap_or(0)
                .checked_add(1).ok_or("id overflow")?;
            tasks.push(Todo { id, done: false, title });
            save(path, &tasks)?;
            Ok(format!("added={id}\n"))
        }
        Command::Done(id) => {
            let task = tasks.iter_mut().find(|task| task.id == id).ok_or("task not found")?;
            task.done = true;
            save(path, &tasks)?;
            Ok(format!("done={id}\n"))
        }
        Command::List => Ok(rows(&tasks)),
        Command::Stats => Ok(format!("saved={} done={}\n", tasks.len(), tasks.iter().filter(|t| t.done).count())),
    }
}

struct Scratch(PathBuf);
impl Scratch {
    fn new() -> Result<Self, String> {
        let stamp = SystemTime::now().duration_since(UNIX_EPOCH).map_err(|e| e.to_string())?.as_nanos();
        let root = std::env::temp_dir().join(format!("qfli-todo-{}-{stamp}", std::process::id()));
        fs::create_dir(&root).map_err(|e| e.to_string())?;
        Ok(Self(root))
    }
}
impl Drop for Scratch { fn drop(&mut self) { let _ = fs::remove_dir_all(&self.0); } }

fn demo() -> Result<(), String> {
    let scratch = Scratch::new()?;
    let path = scratch.0.join("tasks.tsv");
    for args in [vec!["add", "Read", "ownership"], vec!["add", "Build", "CLI"], vec!["done", "1"]] {
        execute(&path, parse_command(&args.into_iter().map(String::from).collect::<Vec<_>>())?)?;
    }
    let restored = load(&path)?;
    assert_eq!(restored.len(), 2);
    assert!(restored[0].done && !restored[1].done);
    print!("{}", execute(&path, Command::List)?);
    print!("{}", execute(&path, Command::Stats)?);
    let invalid = parse_command(&["done".into(), "zero".into()]).is_err();
    let corrupt = scratch.0.join("corrupt.tsv");
    fs::write(&corrupt, "1\t0\tone\n1\t1\ttwo\n").map_err(|e| e.to_string())?;
    println!("bad_id={invalid} malformed={}", load(&corrupt).is_err());
    Ok(())
}

fn run() -> Result<(), String> {
    let mut args: Vec<String> = std::env::args().skip(1).collect();
    if args.is_empty() { return demo(); }
    let path = if args.first().map(String::as_str) == Some("--file") {
        if args.len() < 3 { return Err("--file needs a path and command".into()); }
        let path = PathBuf::from(&args[1]);
        args.drain(..2);
        path
    } else { PathBuf::from("tasks.tsv") };
    print!("{}", execute(&path, parse_command(&args)?)?);
    Ok(())
}

fn main() {
    if let Err(error) = run() { eprintln!("todo: {error}"); std::process::exit(1); }
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn escapes_round_trip_and_rejects_truncation() {
        let title = "tab\tline\nback\\slash";
        assert_eq!(unescape(&escape(title)).unwrap(), title);
        assert!(unescape("trailing\\").is_err());
    }
    #[test]
    fn persistence_keeps_ids_and_errors_do_not_erase_data() {
        let root = Scratch::new().unwrap();
        let path = root.0.join("db");
        execute(&path, Command::Add("first\ttask".into())).unwrap();
        let before = fs::read(&path).unwrap();
        assert!(execute(&path, Command::Done(9)).is_err());
        assert_eq!(fs::read(&path).unwrap(), before);
        assert_eq!(load(&path).unwrap()[0].title, "first\ttask");
    }
}

