        };
        let title = unescape(columns.next().ok_or("missing title")?)?;
        if title.trim().is_empty() { return Err("empty stored title".into()); }
        tasks.push(Todo { id, done, title });
    }
    Ok(tasks)
}

fn save(path: &Path, tasks: &[Todo]) -> Result<(), String> {
    let nonce = SystemTime::now().duration_since(UNIX_EPOCH).map_err(|e| e.to_string())?.as_nanos();
    let temporary = path.with_extension(format!("tmp-{}-{nonce}", std::process::id()));
    let result = (|| -> Result<(), String> {
        let mut file = OpenOptions::new().write(true).create_new(true).open(&temporary)
            .map_err(|e| format!("temporary file: {e}"))?;
        for task in tasks {
            writeln!(file, "{}\t{}\t{}", task.id, u8::from(task.done), escape(&task.title))
                .map_err(|e| format!("write: {e}"))?;
        }
        file.sync_all().map_err(|e| format!("flush: {e}"))?;
        drop(file);
        fs::rename(&temporary, path).map_err(|e| format!("replace: {e}"))
    })();
    if result.is_err() { let _ = fs::remove_file(&temporary); }
    result
}

fn rows(tasks: &[Todo]) -> String {
    tasks.iter().map(|task| format!("{} [{}] {}\n", task.id,
        if task.done { "x" } else { " " }, task.title)).collect()
}

fn execute(path: &Path, command: Command) -> Result<String, String> {
    let mut tasks = load(path)?;
    match command {
        Command::Add(title) => {
            let id = tasks.iter().map(|t| t.id).max().unwrap_or(0)
                .checked_add(1).ok_or("id overflow")?;
            tasks.push(Todo { id, done: false, title });
            save(path, &tasks)?;
            Ok(format!("added={id}\n"))
        }
        Command::Done(id) => {
            let task = tasks.iter_mut().find(|task| task.id == id).ok_or("task not found")?;
            task.done = true;
            save(path, &tasks)?;
            Ok(format!("done={id}\n"))
        }
        Command::Remove(id) => {
            let old_len = tasks.len();
            tasks.retain(|task| task.id != id);
            if tasks.len() == old_len { return Err("task not found".into()); }
            save(path, &tasks)?;
            Ok(format!("removed={id}\n"))
        }
        Command::List => Ok(rows(&tasks)),
        Command::Stats => Ok(format!("saved={} done={}\n", tasks.len(), tasks.iter().filter(|t| t.done).count())),
    }
}

