#[derive(Debug, Clone, PartialEq, Eq)]
struct Todo { id: u64, done: bool, title: String }

#[derive(Debug, PartialEq, Eq)]
enum Command { Add(String), Done(u64), List, Stats }

fn parse_command(args: &[String]) -> Result<Command, String> {
    match args.first().map(String::as_str) {
        Some("add") if args.len() >= 2 => {
            let title = args[1..].join(" ");
            if title.trim().is_empty() { return Err("empty title".into()); }
            Ok(Command::Add(title))
        }
        Some("done") if args.len() == 2 => {
            let id = args[1].parse::<u64>().map_err(|_| "invalid id")?;
            if id == 0 { return Err("id must be positive".into()); }
            Ok(Command::Done(id))
        }
        Some("list") if args.len() == 1 => Ok(Command::List),
        Some("stats") if args.len() == 1 => Ok(Command::Stats),
        _ => Err("usage: [--file PATH] add TITLE | done ID | list | stats".into()),
    }
}

fn escape(title: &str) -> String {
    let mut encoded = String::new();
    for character in title.chars() {
        match character {
            '\\' => encoded.push_str("\\\\"),
            '\t' => encoded.push_str("\\t"),
            '\n' => encoded.push_str("\\n"),
            '\r' => encoded.push_str("\\r"),
            other => encoded.push(other),
        }
    }
    encoded
}

fn unescape(encoded: &str) -> Result<String, String> {
    let mut result = String::new();
    let mut characters = encoded.chars();
    while let Some(character) = characters.next() {
        if character != '\\' { result.push(character); continue; }
        result.push(match characters.next() {
            Some('\\') => '\\', Some('t') => '\t',
            Some('n') => '\n', Some('r') => '\r',
            _ => return Err("invalid title escape".into()),
        });
    }
    Ok(result)
}

fn load(path: &Path) -> Result<Vec<Todo>, String> {
    let text = match fs::read_to_string(path) {
        Ok(text) => text,
        Err(error) if error.kind() == io::ErrorKind::NotFound => return Ok(Vec::new()),
        Err(error) => return Err(format!("read: {error}")),
    };
    let mut seen = BTreeSet::new();
    let mut tasks = Vec::new();
    for (index, line) in text.lines().enumerate() {
        let mut columns = line.splitn(3, '\t');
        let id = columns.next().unwrap_or("").parse::<u64>()
            .map_err(|_| format!("line {}: invalid id", index + 1))?;
        if id == 0 || !seen.insert(id) { return Err("duplicate or zero id".into()); }
        let done = match columns.next() {
            Some("0") => false, Some("1") => true,
            _ => return Err("invalid completion flag".into()),
        };
        let title = unescape(columns.next().ok_or("missing title")?)?;
        if title.trim().is_empty() { return Err("empty stored title".into()); }
        tasks.push(Todo { id, done, title });
    }
    Ok(tasks)
}

