            writeln!(file, "{}\t{}\t{}", task.id, u8::from(task.done), escape(&task.title))
                .map_err(|e| format!("write: {e}"))?;
        }
        file.sync_all().map_err(|e| format!("flush: {e}"))?;
        drop(file);
        fs::rename(&temporary, path).map_err(|e| format!("replace: {e}"))
    })();
    if result.is_err() { let _ = fs::remove_file(&temporary); }
    result
}

