use std::fs;
use std::path::{Path, PathBuf};
use std::sync::{mpsc, Arc, Mutex};
use std::thread;
use std::time::{SystemTime, UNIX_EPOCH};

type Counts = BTreeMap<String, u64>;
struct Job { index: usize, path: PathBuf }
struct Event { index: usize, name: String, result: Result<Counts, String> }
struct Report { counts: Counts, errors: Vec<(String, String)>, processed: usize }

fn count_words(text: &str) -> Counts {
    let mut counts = BTreeMap::new();
    for word in text.split(|c: char| !c.is_alphanumeric()).filter(|word| !word.is_empty()) {
        let normalized: String = word.chars().flat_map(char::to_lowercase).collect();
        *counts.entry(normalized).or_insert(0) += 1;
    }
    counts
}

fn count_file(path: &Path) -> Result<Counts, String> {
    fs::read_to_string(path).map(|text| count_words(&text)).map_err(|error| {
        match error.kind() {
            std::io::ErrorKind::NotFound => "not-found",
            std::io::ErrorKind::InvalidData => "invalid-utf8",
            _ => "io-error",
        }.to_string()
    })
}

fn worker(receiver: Arc<Mutex<mpsc::Receiver<Job>>>, sender: mpsc::Sender<Event>) -> Result<(), String> {
    loop {
        // Only receive is serialized. File I/O and counting happen after the
        // guard is dropped, allowing all workers to process different files.
        let job = {
            let receiver = receiver.lock().map_err(|_| "job queue poisoned")?;
            receiver.recv()
        };
        let job = match job { Ok(job) => job, Err(_) => break };
        // Invalid input is a result for this job, never a worker shutdown.
        // In particular, roots have no file_name and must not strand a sender.
        let (name, result) = match job.path.file_name() {
            Some(name) => (name.to_string_lossy().into_owned(), count_file(&job.path)),
            None => (job.path.display().to_string(), Err("missing-filename".into())),
        };
        let event = Event { index: job.index, name, result };
        if sender.send(event).is_err() { break; }
    }
    Ok(())
}

fn pipeline(paths: Vec<PathBuf>, workers: usize, capacity: usize) -> Result<Report, String> {
    if workers == 0 || capacity == 0 { return Err("workers and capacity must be positive".into()); }
    let submitted = paths.len();
    let (job_tx, job_rx) = mpsc::sync_channel(capacity);
    let queue = Arc::new(Mutex::new(job_rx));
    let (result_tx, result_rx) = mpsc::channel();
    let mut events = thread::scope(|scope| -> Result<Vec<Event>, String> {
        // A separate producer provides backpressure without blocking result
        // collection when the bounded job queue fills.
        let producer = scope.spawn(move || -> Result<(), String> {
            for (index, path) in paths.into_iter().enumerate() {
                job_tx.send(Job { index, path }).map_err(|_| "workers stopped")?;
            }
            Ok(()) // dropping the final job sender closes the worker loop
        });
        let mut handles = Vec::new();
        for _ in 0..workers {
            let receiver = Arc::clone(&queue);
            let sender = result_tx.clone();
            handles.push(scope.spawn(move || worker(receiver, sender)));
        }
        // Only workers retain the receiving endpoint. If they all stop, the
        // producer must observe a disconnected queue instead of blocking.
        drop(queue);
        drop(result_tx);
        // The receiver drains while producer/workers run. No shared mutable
        // count map is needed, and all sender clones must be dropped for EOF.
        let events: Vec<_> = result_rx.into_iter().collect();
        producer.join().map_err(|_| "producer panicked")??;
        for handle in handles { handle.join().map_err(|_| "worker panicked")??; }
        Ok(events)
    })?;
    if events.len() != submitted { return Err("a file result was lost".into()); }
    events.sort_by_key(|event| event.index);
    let mut report = Report { counts: BTreeMap::new(), errors: Vec::new(), processed: submitted };
    for event in events {
        match event.result {
            Ok(counts) => for (word, count) in counts {
                let total = report.counts.entry(word).or_insert(0);
                *total = total.checked_add(count).ok_or("word count overflow")?;
            },
            Err(error) => report.errors.push((event.name, error)),
        }
    }
    Ok(report)
}

fn frequent(report: &Report, minimum: u64) -> Vec<(String, u64)> {
    report.counts.iter().filter(|(_, count)| **count >= minimum)
        .map(|(word, count)| (word.clone(), *count)).collect()
}

fn render(report: &Report) -> String {
    let mut output = String::new();
    for (word, count) in &report.counts { output.push_str(&format!("{word}={count}\n")); }
    output.push_str(&format!("processed={} errors={}\n", report.processed, report.errors.len()));
    for (name, error) in &report.errors { output.push_str(&format!("{name}:{error}\n")); }
    output
}

struct Scratch(PathBuf);
impl Scratch {
    fn new() -> Result<Self, String> {
        let stamp = SystemTime::now().duration_since(UNIX_EPOCH).map_err(|e| e.to_string())?.as_nanos();
        let root = std::env::temp_dir().join(format!("qfli-words-{}-{stamp}", std::process::id()));
        fs::create_dir(&root).map_err(|e| e.to_string())?;
        Ok(Self(root))
    }
}
impl Drop for Scratch { fn drop(&mut self) { let _ = fs::remove_dir_all(&self.0); } }

fn fixture(root: &Path) -> Result<Vec<PathBuf>, String> {
    for (name, text) in [("a.txt", "Rust rust ownership"), ("b.txt", "Ownership with channels; Rust."), ("c.txt", "channels rust")] {
        fs::write(root.join(name), text).map_err(|e| e.to_string())?;
    }
    fs::write(root.join("bad.txt"), [0xff, 0xfe]).map_err(|e| e.to_string())?;
    Ok(["a.txt", "b.txt", "c.txt", "bad.txt", "missing.txt"].map(|name| root.join(name)).to_vec())
}

fn run() -> Result<(), String> {
    let args: Vec<PathBuf> = std::env::args().skip(1).map(PathBuf::from).collect();
    if args.is_empty() {
        let scratch = Scratch::new()?;
        let paths = fixture(&scratch.0)?;
        let report = pipeline(paths.clone(), 3, 2)?;
        // Compare one-worker and multi-worker results to a deterministic oracle.
        let serial = pipeline(paths, 1, 1)?;
        assert_eq!(report.counts, serial.counts);
        assert_eq!(report.errors, serial.errors);
        assert_eq!(report.counts.get("rust"), Some(&4));
        assert_eq!(frequent(&report, 3), vec![("rust".into(), 4)]);
        println!("frequent={:?}", frequent(&report, 3));
        let current = std::env::current_dir().map_err(|e| e.to_string())?;
        let root = current.ancestors().last().ok_or("missing root")?.to_path_buf();
        let invalid = pipeline(vec![root; 8], 3, 2)?;
        assert_eq!(invalid.processed, 8);
        assert_eq!(invalid.errors.len(), 8);
        assert!(invalid.errors.iter().all(|(_, error)| error == "missing-filename"));
        print!("{}", render(&report));
    } else {
        let report = pipeline(args, 3, 2)?;
        print!("{}", render(&report));
        if !report.errors.is_empty() { return Err("one or more inputs failed".into()); }
    }
    Ok(())
}

fn main() {
    if let Err(error) = run() { eprintln!("wordcount: {error}"); std::process::exit(1); }
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn punctuation_and_case_are_normalized() {
        let counts = count_words("Rust, RUST! ownership.");
        assert_eq!(counts.get("rust"), Some(&2));
        assert_eq!(counts.get("ownership"), Some(&1));
    }
    #[test]
    fn validates_limits_and_handles_empty_input() {
        assert!(pipeline(Vec::new(), 0, 1).is_err());
        assert!(pipeline(Vec::new(), 1, 0).is_err());
        assert!(pipeline(Vec::new(), 2, 1).unwrap().counts.is_empty());
    }
    #[test]
    fn file_errors_do_not_drop_other_results() {
        let root = Scratch::new().unwrap();
        let paths = fixture(&root.0).unwrap();
        let report = pipeline(paths, 2, 1).unwrap();
        assert_eq!(report.processed, 5);
        assert_eq!(report.errors.len(), 2);
        assert_eq!(report.counts.get("channels"), Some(&2));
    }
}

