/// Independent oracle used by the integration tests to validate complete CLI output.
pub fn nonempty_lines(output: &str) -> Vec<&str> {
    output.lines().filter(|line| !line.trim().is_empty()).collect()
}
pub fn value<'a>(output: &'a str, key: &str) -> Option<&'a str> {
    output.lines().find_map(|line| line.strip_prefix(key))
}
#[cfg(test)]
mod tests {
    #[test]
    fn output_oracle_preserves_values_and_rejects_missing_keys() {
        assert_eq!(super::value("a=2\nb=3\n", "a="), Some("2"));
        assert_eq!(super::value("a=2\n", "missing="), None);
        assert_eq!(super::nonempty_lines("a\n\nb\n"), vec!["a", "b"]);
    }
}

