use std::process::Command;

#[test]
fn binary_demo_matches_the_complete_contract() {
    let result = Command::new(env!("CARGO_BIN_EXE_rust_capstone_165")).output().expect("run demo");
    assert!(result.status.success(), "{}", String::from_utf8_lossy(&result.stderr));
    let stdout = String::from_utf8(result.stdout).unwrap().replace("\r\n", "\n");
    assert_eq!(stdout, "channels=2\nownership=2\nrust=4\nwith=1\nprocessed=5 errors=2\nbad.txt:invalid-utf8\nmissing.txt:not-found\n");
    assert!(!rust_capstone_165::nonempty_lines(&stdout).is_empty());
}

#[test]
fn failed_external_input_returns_nonzero_without_a_panic() {
    let result = Command::new(env!("CARGO_BIN_EXE_rust_capstone_165"))
        .arg("qfli-definitely-missing-input-165.txt").output().unwrap();
    assert!(!result.status.success());
    assert!(String::from_utf8_lossy(&result.stdout).contains("processed=1 errors=1"));
    assert!(!String::from_utf8_lossy(&result.stderr).contains("panicked"));
}

#[test]
fn root_paths_exceeding_workers_and_queue_capacity_finish_with_errors() {
    use std::process::Stdio;
    use std::time::{Duration, Instant};
    let current = std::env::current_dir().unwrap();
    let root = current.ancestors().last().unwrap();
    let mut child = Command::new(env!("CARGO_BIN_EXE_rust_capstone_165"))
        .args(std::iter::repeat(root).take(8))
        .stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();
    let deadline = Instant::now() + Duration::from_secs(10);
    loop {
        if child.try_wait().unwrap().is_some() { break; }
        if Instant::now() >= deadline {
            let _ = child.kill();
            let _ = child.wait();
            panic!("root-path jobs blocked the bounded queue");
        }
        std::thread::sleep(Duration::from_millis(10));
    }
    let result = child.wait_with_output().unwrap();
    assert!(!result.status.success());
    let output = String::from_utf8(result.stdout).unwrap();
    assert!(output.contains("processed=8 errors=8"), "{output}");
    assert_eq!(output.matches("missing-filename").count(), 8);
    assert!(!String::from_utf8_lossy(&result.stderr).contains("panicked"));
}

