use std::process::Command;

#[test]
fn binary_demo_matches_the_complete_contract() {
    let result = Command::new(env!("CARGO_BIN_EXE_rust_capstone_166")).output().expect("run demo");
    assert!(result.status.success(), "{}", String::from_utf8_lossy(&result.stderr));
    let stdout = String::from_utf8(result.stdout).unwrap().replace("\r\n", "\n");
    assert_eq!(stdout, "task1=ok:42\ntask2=ok:14\ntask3=cancelled\npending=3 completed=3\noverflow=true null_status=-1\n");
    assert!(!rust_capstone_166::nonempty_lines(&stdout).is_empty());
}

#[test]
fn queue_finishes_pending_and_cancelled_tasks_on_repeated_runs() {
    for _ in 0..3 {
        let result = Command::new(env!("CARGO_BIN_EXE_rust_capstone_166")).output().unwrap();
        assert!(result.status.success());
        let output = String::from_utf8(result.stdout).unwrap();
        assert_eq!(rust_capstone_166::value(&output, "task3="), Some("cancelled"));
        assert_eq!(rust_capstone_166::value(&output, "pending="), Some("3 completed=3"));
    }
}
